package com.greenocean.backend;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
class PhaseO1MigrationTest extends MigrationTestSupport {
 @Test void populatedN3WritingAndLegacyProgressRemainUnchanged(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_o1_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("61").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));
  try{UUID user=db.queryForObject("INSERT INTO users(email,password_hash,status) VALUES('o1-upgrade@example.test','synthetic','ACTIVE') RETURNING id",UUID.class);UUID journal=db.queryForObject("INSERT INTO wellbeing_journal_entries(user_id,title,body) VALUES (?,'Legacy title','متن محفوظ 🌿') RETURNING id",UUID.class,user);UUID goal=db.queryForObject("INSERT INTO wellbeing_goals(user_id,title,cadence,progress) VALUES (?,'Legacy goal','optional',45) RETURNING id",UUID.class,user);var paths=db.queryForList("SELECT to_jsonb(t)::text AS record FROM guided_growth_paths t ORDER BY id");var f=Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("62").load();f.migrate();f.validate();f.migrate();assertThat(db.queryForObject("SELECT body FROM wellbeing_journal_entries WHERE id=?",String.class,journal)).isEqualTo("متن محفوظ 🌿");assertThat(db.queryForObject("SELECT legacy_progress FROM wellbeing_goals WHERE id=?",Integer.class,goal)).isEqualTo(45);assertThat(db.queryForList("SELECT to_jsonb(t)::text AS record FROM guided_growth_paths t ORDER BY id")).isEqualTo(paths);assertThat(db.queryForObject("SELECT count(*) FROM wellbeing_goal_steps",Integer.class)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM wellbeing_prompt_versions WHERE status='PUBLISHED'",Integer.class)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM wellbeing_daily_answers",Integer.class)).isZero();}finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}
 }
}
